-- 35 Neon Signs: flickers the OPEN sign and its light. The outlines, the
-- glow under each tube and the shadows are the engine's (`outline` and
-- `shadow` on a world text). Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/35-neon-signs.scene"
local post_on = nav.post_all_on(SCENE)
local captions = true
local sign, light, status
local t = 0
local off_until = 0

function init(entity)
    sign = Entity.find_by_name("SignOpen")
    light = Entity.find_by_name("LightOpen")
    status = Entity.find_by_name("Status")
    if status then Text.set(status, nav.post_status(post_on)) end
end

function update(entity, dt)
    nav.tick(SCENE)
    if nav.post_keys(post_on) and status then Text.set(status, nav.post_status(post_on)) end
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_captions(captions) end
    t = t + dt
    -- A tired tube: now and then it drops out for a moment, twice.
    if t > off_until + 0.6 and math.random() < dt * 0.5 then
        off_until = t + 0.08 + math.random() * 0.12
    end
    local on = t > off_until
    local k = on and (1.0 + 0.04 * math.sin(t * 50.0)) or 0.12
    if sign then Text.set_color(sign, 0.80 * 1.8 * k, 1.8 * k, 1.8 * k, 1.0) end
    if light then Lighting.set_intensity(light, 1.2 * k) end
end
